"""Retain every emitted machine-block interval without changing generated bytes."""
from pathlib import Path
import hashlib
import json
import re
import resource
import subprocess
import sys

sys.dont_write_bytecode = True
resource.setrlimit(resource.RLIMIT_CORE, (0, 0))
resource.setrlimit(resource.RLIMIT_FSIZE, (64 * 1024 * 1024, 64 * 1024 * 1024))
root = Path.cwd()
work = Path(__file__).resolve().parent
folder = root / 'bin/linux-gcc/portable-execution-attribution'
settings = json.loads((work / 'emission-settings.json').read_text())
source = folder / 'endpoint.s'
annotated = folder / 'endpoint-machine-blocks.s'
output = folder / 'endpoint-machine-blocks.o'
mapping = work / 'machine-block-assembly.json'
assert not any(p.exists() for p in (annotated, output, mapping))
lines = source.read_text().splitlines(keepends=True)
functions = ['cs_variant', 'cs_co_variant', 'cs_co_variant.resume', 'cs_co_variant.destroy']
header = re.compile(r'^(?:\.LBB(\d+)_(\d+):|# %bb\.(\d+):)')
insertions = {}
blocks = []
current = None
pending = []

def insert(at, label):
    insertions.setdefault(at, []).append(label + ':\n')

def finish(end_at):
    seen = set()
    for index, (at, number, kind) in enumerate(pending):
        assert number not in seen
        seen.add(number)
        stop = pending[index + 1][0] if index + 1 < len(pending) else end_at
        # A trailing alignment directive emits bytes before the next block.
        # Exclude those bytes from this block instead of attributing its NOPs.
        tail = stop
        while tail > at + 1:
            line = lines[tail - 1].strip()
            if not line or line.startswith('#') or line.startswith('.p2align'):
                tail -= 1
            else:
                break
        aligns = [i for i in range(tail, stop) if lines[i].lstrip().startswith('.p2align')]
        boundary = min(aligns) if aligns else stop
        assert not any(lines[i].lstrip().startswith('.p2align') for i in range(at + 1, boundary))
        start_label = f'.Lsirius_machine_{current}_{number}'
        end_label = start_label + '_end'
        insert(at + 1, start_label)
        insert(boundary, end_label)
        origin = re.search(r'#\s+%([^\s]+)', lines[at][header.match(lines[at]).end():])
        blocks.append({'function': functions[current], 'function_ordinal': current,
                       'machine_block': number, 'header_line': at + 1,
                       'boundary_line': boundary + 1, 'header_kind': kind,
                       'header': lines[at].rstrip('\n'),
                       'ir_comment': origin.group(1) if origin else None,
                       'start_symbol': start_label, 'end_symbol': end_label})

for at, line in enumerate(lines):
    match = re.match(r'^(cs_variant|cs_co_variant(?:\.resume|\.destroy)?):', line)
    if match:
        assert current is None
        current = functions.index(match.group(1))
        pending = []
    match = header.match(line)
    if match:
        assert current is not None
        if match.group(1) is not None:
            assert int(match.group(1)) == current
        pending.append((at, int(match.group(2) or match.group(3)),
                        'retained_label' if match.group(1) is not None else 'fallthrough_comment'))
    if re.match(r'^\.Lfunc_end\d+:', line):
        assert current is not None and pending
        assert int(re.search(r'\d+', line).group()) == current
        finish(at)
        current = None
assert current is None and len(blocks) == 8582
result = ''.join(''.join(insertions.get(at, [])) + line for at, line in enumerate(lines))
assert ''.join(line for line in result.splitlines(keepends=True)
               if not line.startswith('.Lsirius_machine_')) == ''.join(lines)
annotated.write_text(result)
mapping.write_text(json.dumps({'assembly_sha256': hashlib.sha256(source.read_bytes()).hexdigest(),
                              'annotated_assembly_sha256': hashlib.sha256(annotated.read_bytes()).hexdigest(),
                              'scope': 'All emitted machine-block headers. IR comments are descriptive provenance, '
                                       'not a one-to-one source-operation contract. Padding is excluded.',
                              'blocks': blocks}, indent=2) + '\n')
subprocess.run(['/usr/bin/llvm-mc-18', '--filetype=obj', '--save-temp-labels',
                '--large-code-model', '--triple=' + settings['triple'],
                '--mcpu=' + settings['cpu'], '--mattr=' + settings['features'],
                str(annotated), '-o', str(output)], check=True)
assert output.is_file() and output.stat().st_size < 64 * 1024 * 1024
